def parse_ports(lines):
    seen = set()
    for line in lines:
        parts = line.split()
        if len(parts) >= 2:
            protocol = parts[0]
            status = parts[1]
            if protocol == 'tcp' and status == 'open':
                port_str = protocol.split('/')[1]
                port = int(port_str)
                if port not in seen:
                    seen.add(port)
    return sorted(list(seen))
