def parse_ports(lines):
    ports = []
    for line in lines:
        parts = line.split()
        if len(parts) >= 2:
            protocol_port = parts[0]
            protocol, port_str = protocol_port.split('/')
            if protocol == 'tcp' and port_str in range(0, 65536):
                ports.append(int(port_str))
    return sorted(set(ports))
